// cop repulsion for driving: returns {push (add to steer, left/right), front (nearest cop in ahead slices, 50 = none)}
function copAvoid(o) {
  let push = 0, front = 50;
  for (let i = 0; i < 8; i++) {
    const d = o.pie.cop[i];
    if (d >= 25) continue;
    push -= (25 - d) / 25 * Math.sin(i * Math.PI / 4);
    if (i === 0 || i === 1 || i === 7) front = Math.min(front, d);
